import math

def sigmoid(z):
    return 1 / (1 + math.exp(-z))

def train(X, y, lr, iters):
    Xb = [row + [1] for row in X]
    n, m = len(Xb), len(Xb[0])
    w = [0.0] * m
    for _ in range(iters):
        p = [sigmoid(sum(a * b for a, b in zip(row, w))) for row in Xb]
        grad = [sum((p[i] - y[i]) * Xb[i][j] for i in range(n)) / n for j in range(m)]
        w = [w[j] - lr * grad[j] for j in range(m)]
    return [round(v, 3) for v in w]

def predict(X, w):
    return [1 if sigmoid(sum(a * b for a, b in zip(row + [1], w))) >= 0.5 else 0 for row in X]

def scores(y_true, y_pred):
    tp = fp = fn = tn = 0
    for t, p in zip(y_true, y_pred):
        if t == 1 and p == 1:
            tp += 1
        elif t == 0 and p == 1:
            fp += 1
        elif t == 1 and p == 0:
            fn += 1
        else:
            tn += 1
    acc = (tp + tn) / len(y_true)
    prec = tp / (tp + fp) if tp + fp else 0
    rec = tp / (tp + fn) if tp + fn else 0
    f1 = 2 * prec * rec / (prec + rec) if prec + rec else 0
    return tp, fp, fn, tn, round(acc, 3), round(prec, 3), round(rec, 3), round(f1, 3)

