import math

def fit(X, y):
    model = {}
    for c in sorted(set(y)):
        rows = [r for r, t in zip(X, y) if t == c]
        cols = list(zip(*rows))
        means = [sum(col) / len(col) for col in cols]
        vars_ = [sum((v - m) ** 2 for v in col) / len(col) for col, m in zip(cols, means)]
        model[c] = (len(rows) / len(X), means, vars_)
    return model

def predict(model, x):
    def score(c):
        prior, means, vars_ = model[c]
        s = math.log(prior)
        for v, m, var in zip(x, means, vars_):
            s += -0.5 * math.log(2 * math.pi * var) - (v - m) ** 2 / (2 * var)
        return s
    return max(model, key=score)

