import math

def _props(labels):
    n = len(labels)
    return [labels.count(c) / n for c in set(labels)]

def gini(labels):
    return round(1 - sum(p * p for p in _props(labels)), 4)

def entropy(labels):
    return round(-sum(p * math.log(p, 2) for p in _props(labels)), 4)

def best_split(xs, ys):
    vals = sorted(set(xs))
    best = None
    for a, b in zip(vals, vals[1:]):
        t = (a + b) / 2
        left = [y for x, y in zip(xs, ys) if x <= t]
        right = [y for x, y in zip(xs, ys) if x > t]
        w = (len(left) * gini(left) + len(right) * gini(right)) / len(ys)
        w = round(w, 4)
        if best is None or w < best[1]:
            best = (t, w)
    return best

