def train_svm(X, y, lr, lam, epochs):
    w = [0.0] * len(X[0])
    b = 0.0
    for _ in range(epochs):
        for x, t in zip(X, y):
            margin = t * (sum(a * c for a, c in zip(w, x)) - b)
            if margin >= 1:
                w = [wi - lr * (2 * lam * wi) for wi in w]
            else:
                w = [wi - lr * (2 * lam * wi - t * xi) for wi, xi in zip(w, x)]
                b -= lr * t
    return [round(v, 3) for v in w], round(b, 3)

