        fill = strategy
    elif strategy == "mean":
        fill = sum(known) / len(known)
    elif strategy == "median":
        s = sorted(known)
        n = len(s)
        fill = s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2
    else:
        counts = {}
        for v in known:
            counts[v] = counts.get(v, 0) + 1
        best = max(counts.values())
        fill = min(v for v in counts if counts[v] == best)
    return [fill if v is None else v for v in col]

