import math

def knn_predict(X_train, y_train, x, k):
    d = lambda i: math.sqrt(sum((a - b) ** 2 for a, b in zip(X_train[i], x)))
    near = sorted(range(len(X_train)), key=d)[:k]
    counts = {}
    for i in near:
        counts[y_train[i]] = counts.get(y_train[i], 0) + 1
    best = max(counts.values())
    return min(c for c in counts if counts[c] == best)

def kfold(n, k):
    out, start = [], 0
    for f in range(k):
        size = n // k + (1 if f < n % k else 0)
        val = list(range(start, start + size))
        train = [i for i in range(n) if i < start or i >= start + size]
        out.append((train, val))
        start += size
    return out

