def _d2(a, b):
    return sum((x - y) ** 2 for x, y in zip(a, b))

def kmeans(X, centers, max_iter):
    centers = [list(c) for c in centers]
    labels = None
    for _ in range(max_iter):
        new = [min(range(len(centers)), key=lambda j: _d2(p, centers[j])) for p in X]
        if new == labels:
            break
        labels = new
        for j in range(len(centers)):
            pts = [p for p, l in zip(X, labels) if l == j]
            if pts:
                centers[j] = [sum(c) / len(pts) for c in zip(*pts)]
    return labels, [[round(v, 3) for v in c] for c in centers]

def inertia(X, labels, centers):
    return round(sum(_d2(p, centers[l]) for p, l in zip(X, labels)), 3)

