solution:
import math

def silhouette(X, labels):
    dist = lambda p, q: math.sqrt(sum((a - b) ** 2 for a, b in zip(p, q)))
    total = 0
    for i, p in enumerate(X):
        own = [j for j in range(len(X)) if labels[j] == labels[i] and j != i]
        if not own:
            continue
        a = sum(dist(p, X[j]) for j in own) / len(own)
        b = min(
            sum(dist(p, X[j]) for j in range(len(X)) if labels[j] == c) / labels.count(c)
            for c in set(labels) if c != labels[i]
        )
        total += (b - a) / max(a, b)
    return round(total / len(X), 4)

