solution:
def _pct(s, p):
    pos = p * (len(s) - 1)
    lo = int(pos)
    hi = min(lo + 1, len(s) - 1)
    return s[lo] + (pos - lo) * (s[hi] - s[lo])

def quartiles(xs):
    s = sorted(xs)
    return _pct(s, 0.25), _pct(s, 0.75)

def iqr_outliers(xs):
    q1, q3 = quartiles(xs)
    iqr = q3 - q1
    return [x for x in xs if x < q1 - 1.5 * iqr or x > q3 + 1.5 * iqr]

