solution:
import math

def nearest(minority, i, k):
    d = lambda j: math.sqrt(sum((a - b) ** 2 for a, b in zip(minority[i], minority[j])))
    others = [j for j in range(len(minority)) if j != i]
    return sorted(others, key=d)[:k]

def smote_sample(minority, i, j, lam):
    return [round(a + lam * (b - a), 3) for a, b in zip(minority[i], minority[j])]

def class_weights(y):
    classes = sorted(set(y))
    return {c: round(len(y) / (len(classes) * y.count(c)), 3) for c in classes}

def _mse(model, X, y):
    return sum((model(r) - t) ** 2 for r, t in zip(X, y)) / len(y)

def perm_importance(model, X, y, perms):
    base = _mse(model, X, y)
    out = []
    for j in range(len(X[0])):
        Xp = [row[:j] + [X[perms[j][i]][j]] + row[j + 1:] for i, row in enumerate(X)]
        out.append(round(_mse(model, Xp, y) - base, 3))
    return out

